# Instructions ----
#' This file follows the format generated by FIMS:::use_testthat_template().
#' Necessary tests include input and output (IO) correctness [IO
#' correctness], edge-case handling [Edge handling], and built-in errors and
#' warnings [Error handling]. See `?FIMS:::use_testthat_template` for more
#' information. Every test should have a @description tag, which can only span
#' one lines, that will be used in the bookdown report of the results from
#' {testthat}. This line can be more than 80 characters.

# call_module ----
## Setup ----
# Logistic selectivity over 12 ages, with its 2 parameters by label.
logistic_parameters <- list(inflection_point = 4, slope = 1)

## IO correctness ----
test_that("`call_module()` works with correct inputs", {
  #' @description Test that `call_module()` calls the function for the module type with its parameters by label.
  expect_equal(
    object = FIMS:::call_module(
      FIMS:::selectivity_functions, "Logistic",
      age = 1:12, parameters = logistic_parameters
    ),
    expected = FIMS:::logistic_selectivity(1:12, 4, 1)
  )
})

## Edge handling ----
# No edge cases to test.

## Error handling ----
test_that("`call_module()` returns correct error messages", {
  #' @description Test that `call_module()` errors for a module type that has no function.
  expect_error(
    object = FIMS:::call_module(
      FIMS:::selectivity_functions, "Gompertz",
      age = 1:12, parameters = logistic_parameters
    ),
    regexp = "no function for module type"
  )
  #' @description Test that `call_module()` names the parameters when one has no rows, here the slope.
  expect_error(
    object = FIMS:::call_module(
      FIMS:::selectivity_functions, "Logistic",
      age = 1:12, parameters = logistic_parameters["inflection_point"]
    ),
    regexp = "has the parameters"
  )
  #' @description Test that `call_module()` names the parameters when the rows are for another module type.
  expect_error(
    object = FIMS:::call_module(
      FIMS:::selectivity_functions, "DoubleLogistic",
      age = 1:12, parameters = logistic_parameters
    ),
    regexp = "inflection_point_asc"
  )
})
